-- ExamGrind verified daily current-affairs desk: 5 November 2026.
-- Recovery coverage: substantive releases from 3-4 November 2026. Every item was checked at its linked official source.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-11-05-ftsc-continuation$$, $$2026-11-05$$,
$$Cabinet extends Fast Track Special Courts scheme through March 2031$$,
$$The Union Cabinet approved a five-year continuation of the Centrally Sponsored Scheme for Fast Track Special Courts, including exclusive POCSO Courts. The extension runs from 1 April 2026 to 31 March 2031 and carries a total outlay of Rs 3,788.04 crore.$$,
$$This is a high-value polity and social-justice update. It connects the POCSO Act, the Nirbhaya Fund, Centre-State scheme financing and the judicial response to sexual-offence case pendency.$$,
$$FTSCs are dedicated courts for faster disposal of specified rape and POCSO cases; they are not the same as every fast-track court in India. The approved plan provides for up to 850 FTSCs, compared with 779 currently functional, and the Department of Justice will coordinate implementation with States and Union Territories. The release says the Central share is funded from the Nirbhaya Fund.$$,
$$Cabinet approves continuation of the Centrally Sponsored Scheme for Fast Track Special Courts$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332483$$,
$$Department of Justice / Press Information Bureau$$, $$2026-11-04$$,
$$["The continuation period is 1 April 2026 to 31 March 2031.","The scheme covers FTSCs, including exclusive POCSO Courts.","The total approved outlay is Rs 3,788.04 crore.","The Central share is to be funded from the Nirbhaya Fund."]$$::jsonb,
$$[{"question":"Which fund is named as the source of the Central share for the extended FTSC scheme?","answer":"The Nirbhaya Fund."}]$$::jsonb,
$${"title":"FTSC scheme: approval to case disposal","steps":["A sexual-offence case enters the justice system.","A dedicated FTSC can provide specialised judicial and prosecutorial support.","Centre and participating States/UTs fund operational capacity.","Monitoring focuses on disposal and pendency outcomes."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-vistar-statistics-scheme$$, $$2026-11-05$$,
$$Cabinet approves VISTAR to upgrade India’s official-statistics system$$,
$$The Cabinet approved the Viksit Bharat Initiative for Statistical Transformation, Analytics & Research (VISTAR) for FY 2026-27 to FY 2030-31, with an outlay of Rs 4,371.10 crore. The central-sector scheme is intended to improve the timeliness, granularity and interoperability of official data.$$,
$$VISTAR is relevant to economy and governance questions because it links MoSPI’s surveys, economic census work, State statistical capacity and data-governance reform. It is a system-strengthening scheme, not a single new index.$$,
$$The scheme has three components: Comprehensive Statistical Operations and Strengthening of Ecosystem; Support for Statistical Strengthening; and the Economic Census. MoSPI says it plans 59 surveys in the Sixteenth Finance Commission cycle and will use digital processes and AI/ML in activities such as data processing, validation and analysis. The proposed 8th Economic Census is one component, not the whole scheme.$$,
$$Cabinet approves Viksit Bharat Initiative for Statistical Transformation, Analytics & Research (VISTAR)$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332480$$,
$$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-11-04$$,
$$["VISTAR is approved for FY 2026-27 to FY 2030-31.","Its approved outlay is Rs 4,371.10 crore.","MoSPI is the ministry whose statistical and data-management activities it covers.","The scheme includes a Support for Statistical Strengthening component for States and UTs."]$$::jsonb,
$$[{"question":"Is VISTAR merely a new economic index?","answer":"No. It is a broader central-sector scheme for official-statistics operations, State capacity and the Economic Census."}]$$::jsonb,
$${"title":"VISTAR statistical architecture","steps":["Surveys and administrative data create evidence.","Digital collection and validation improve data quality and timeliness.","Harmonised datasets support analysis and sharing.","Officials and States use granular evidence for policy design."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-critical-mineral-processing-capex$$, $$2026-11-05$$,
$$Cabinet clears capital support for domestic lithium and nickel processing$$,
$$The Cabinet approved a Rs 2,814 crore, five-year Capex Support Scheme to promote domestic processing of critical minerals. It targets lithium and nickel ores or intermediates to make high-purity compounds, with cobalt expected as a nickel-processing by-product.$$,
$$This is an economy, science and energy-security update. It tests the distinction between mining, beneficiation and processing, and links critical-mineral value chains with batteries, electronics, defence and clean-energy technologies.$$,
$$The scheme period is FY 2026-27 to FY 2030-31. It envisages four plants: two lithium plants with at least 30 kilotonnes each and two nickel plants with at least 50 kilotonnes each. A capital subsidy of 30% of eligible investment is proposed, with selection through technical qualification followed by financial bidding; the announcement does not mean the plants are already operational.$$,
$$Cabinet Approves Capex Support Scheme to Promote Critical Mineral Processing$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332476$$,
$$Ministry of Mines / Press Information Bureau$$, $$2026-11-04$$,
$$["The scheme’s total outlay is Rs 2,814 crore over five years.","It targets lithium and nickel processing; cobalt may be recovered from nickel processing.","It envisages two lithium and two nickel processing plants.","The announced capital subsidy is 30% of eligible investment."]$$::jsonb,
$$[{"question":"Does this scheme fund only extraction of critical minerals?","answer":"No. It supports domestic processing of lithium and nickel ores or intermediates into high-purity compounds."}]$$::jsonb,
$${"title":"Critical-mineral value addition","steps":["Ore or intermediate material is sourced.","Domestic facilities process it into high-purity compounds.","Battery, electronics and other manufacturers use the processed inputs.","Value addition and supply-chain resilience increase within India."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-grid-scale-storage-vgf$$, $$2026-11-05$$,
$$Cabinet approves VGF scheme for 92 GWh of grid-scale energy storage$$,
$$The Cabinet approved a Viability Gap Funding scheme with Rs 14,500 crore of support for 92 GWh of new grid-scale energy-storage capacity over FY 2026-27 to FY 2030-31. The planned mix is 60 GWh of pumped storage, 30 GWh of battery storage and 2 GWh of alternative storage technologies.$$,
$$This is central to power-sector and environment preparation. It illustrates why renewable-energy expansion requires balancing resources, and why storage capacity is measured in energy units such as GWh rather than only generating capacity in GW.$$,
$$Viability Gap Funding is public financial support intended to improve the commercial feasibility of socially or strategically useful infrastructure. The release says capacity will be allocated through tariff-based competitive bidding. It also specifies a minimum domestic-content requirement of 40% for BESS projects; an approval is not proof that all 92 GWh has been commissioned.$$,
$$Cabinet approves Viability Gap Funding Scheme for development of 92 GWh Grid-Scale Energy Storage Systems$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332474$$,
$$Ministry of Power / Press Information Bureau$$, $$2026-11-04$$,
$$["The scheme provides Rs 14,500 crore of VGF support.","It targets 92 GWh of as-yet-uncommissioned storage capacity.","The planned mix is 60 GWh PSP, 30 GWh BESS and 2 GWh alternative technologies.","BESS projects carry a 40% minimum domestic-content requirement."]$$::jsonb,
$$[{"question":"What does GWh measure in the storage announcement?","answer":"Energy-storage capacity: the amount of electrical energy a system can store or deliver, not merely its instantaneous power rating."}]$$::jsonb,
$${"title":"How grid storage supports renewables","steps":["Variable renewable generation produces power at changing times.","Storage charges when electricity is available.","It discharges during high demand or lower renewable output.","The grid gains balancing flexibility and reliability."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-agniveer-absorption-pathway$$, $$2026-11-05$$,
$$Cabinet adds a two-year engagement route for remaining Agniveers$$,
$$The Cabinet approved a further two-year engagement period for willing Agniveers who are not selected for regular employment after the first four years. The official release says the existing merit-based offer of regular employment for 25% continues; after the additional period, willing candidates who meet selection criteria will be offered enrolment as regular soldiers.$$,
$$This is a major defence-governance and public-policy development. For examinations, retain the sequence accurately: the regular-employment offer for 25% remains merit-based, while the later pathway for the remaining group is conditional rather than automatic.$$,
$$The Agnipath scheme continues. According to the release, the second engagement period comes with higher remuneration, an enhanced Seva Nidhi package and seniority benefits. It applies to the remaining 75% who are willing to take it; future regular enrolment still requires willingness and meeting the applicable selection criteria.$$,
$$Cabinet creates a pathway for all Agniveers to be absorbed in Defence Forces$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332524$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-11-04$$,
$$["The pre-existing merit-based regular-employment offer is for 25% of Agniveers.","The remaining 75% may take a further two-year engagement period if willing.","Regular enrolment after that period remains subject to willingness and selection criteria.","The release says the Agnipath scheme will continue."]$$::jsonb,
$$[{"question":"Does the release say that every Agniveer is immediately made a regular soldier after four years?","answer":"No. It retains merit-based selection for 25% and creates a conditional additional two-year route for the remaining willing Agniveers."}]$$::jsonb,
$${"title":"Agniveer engagement pathway","steps":["An Agniveer completes the initial engagement.","Merit-based regular employment is offered to 25%.","Willing members of the remaining group may take a two-year extension.","After that period, regular enrolment depends on willingness and selection criteria."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-trai-interconnection-amendment$$, $$2026-11-05$$,
$$TRAI shifts telecom-interconnection framework toward service-area and IP-based links$$,
$$TRAI released the Telecommunication Interconnection (Third Amendment) Regulations, 2026, to take effect on 1 January 2027. The changes provide for interconnection at the Licensed Service Area level and require new interconnections to be IP-based.$$,
$$This is a strong regulator-and-telecom-infrastructure item. It tests TRAI’s statutory role under the TRAI Act, 1997 and the technical idea of interconnection, which lets customers of different telecom networks communicate.$$,
$$Existing traffic at older Short Distance and Long Distance Charging Area points of interconnection is to move to Licensed Service Area points over three years in phases. Existing E1/TDM points are also to migrate to IP-based interconnection over three years. A point of interconnection, or POI, is where networks hand traffic to one another; it is not a consumer-facing service centre.$$,
$$TRAI releases The Telecommunication Interconnection (Third Amendment) Regulations, 2026$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331941$$,
$$Telecom Regulatory Authority of India / Press Information Bureau$$, $$2026-11-03$$,
$$["The amendment regulations take effect on 1 January 2027.","TRAI is empowered on interconnection matters under section 11(1)(b) of the TRAI Act, 1997.","New interconnections after commencement must be IP-based.","Older SDCA/LDCA and E1/TDM arrangements are to migrate in phases over three years."]$$::jsonb,
$$[{"question":"What does telecom interconnection enable?","answer":"It enables traffic to pass between networks so users of different service providers can communicate."}]$$::jsonb,
$${"title":"Telecom interconnection migration","steps":["Networks agree how to hand traffic to each other.","Licensed-Service-Area POIs replace older charging-area arrangements.","New links use IP-based interconnection.","Phased migration improves modern network management and performance."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-asi-2024-25-publications$$, $$2026-11-05$$,
$$MoSPI releases detailed ASI 2024-25 factory-sector publications$$,
$$MoSPI released Annual Survey of Industries 2024-25 Volume I, Summary Results of the Factory Sector, unit-level data and metadata. The release reports 9.28% year-on-year GVA growth for the manufacturing corporate sector and highlights new detailed factory-sector tables.$$,
$$This is a core official-statistics update for economy preparation. It is useful for distinguishing ASI from household surveys and for understanding how factory-sector data feed National Accounts Statistics at national and State levels.$$,
$$ASI examines the structure and growth of registered manufacturing, covering measures such as output, value added, employment and capital formation. The detailed tables use NIC 2008 classification: all-India results are available at 2-, 3- and 4-digit levels, while State/UT results are provided at 2- and 3-digit levels. The survey reference year is FY 2024-25, even though the release came later.$$,
$$Publications of Annual Survey of Industries 2024-25$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332475$$,
$$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-11-04$$,
$$["ASI 2024-25 covers registered manufacturing-sector information.","The manufacturing corporate sector’s reported GVA growth was 9.28% year on year.","The release disseminates Volume I, summary results, unit-level data and metadata.","ASI results support National Accounts Statistics at national and State levels."]$$::jsonb,
$$[{"question":"Does ASI primarily describe household consumption or the registered factory sector?","answer":"The registered factory sector; it provides information on manufacturing output, value added, employment, capital and related measures."}]$$::jsonb,
$${"title":"ASI data to economic measurement","steps":["Registered factories report production and employment information.","ASI compiles sector and State-level measures.","NIC classification organises industrial results.","The results inform industrial analysis and national accounts."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-ndc-tia-road-freight$$, $$2026-11-05$$,
$$NITI Aayog and GIZ sign road-freight decarbonisation implementation agreement$$,
$$NITI Aayog and GIZ signed an implementation agreement under Phase II of the Nationally Determined Contribution–Transport Initiative for Asia on 3 November. The collaboration is intended to accelerate decarbonisation of India’s road-freight sector.$$,
$$This is an exam-relevant climate-governance and transport-policy update. It links Nationally Determined Contributions with the difficult task of lowering emissions from medium- and heavy-duty freight vehicles, which need technology, charging, finance and regulatory support.$$,
$$NDC-TIA II is a regional initiative supported by the German Government’s International Climate Initiative. The release names WRI India, ICCT India and Agora Energiewende among implementing partners. An implementation agreement formalises cooperation; it does not by itself establish a new mandatory vehicle standard or prove a nationwide fleet conversion.$$,
$$NITI Aayog and GIZ India Sign Implementation Agreement under NDC-TIA II$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332576$$,
$$NITI Aayog / Press Information Bureau$$, $$2026-11-04$$,
$$["The agreement was signed on 3 November 2026.","It is under the Nationally Determined Contribution–Transport Initiative for Asia Phase II.","NDC-TIA II is supported by Germany’s International Climate Initiative.","The collaboration focuses on decarbonising India’s road-freight sector."]$$::jsonb,
$$[{"question":"Why is road-freight decarbonisation more than simply buying electric trucks?","answer":"The release points to the need for charging infrastructure, financing mechanisms and an enabling regulatory framework alongside vehicle technology."}]$$::jsonb,
$${"title":"Road-freight decarbonisation","steps":["Freight vehicles create transport emissions.","Technology, charging and financing determine adoption feasibility.","Institutions coordinate pilots, policy support and evidence.","Lower-carbon freight can contribute to NDC and long-term climate goals."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-05-ftsc-continuation$$,
$$2026-11-05-vistar-statistics-scheme$$,
$$2026-11-05-critical-mineral-processing-capex$$,
$$2026-11-05-grid-scale-storage-vgf$$,
$$2026-11-05-agniveer-absorption-pathway$$,
$$2026-11-05-trai-interconnection-amendment$$,
$$2026-11-05-asi-2024-25-publications$$,
$$2026-11-05-ndc-tia-road-freight$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
